mapper.select:
SELECT SQL_CALC_FOUND_ROWS ROW_NUMBER() OVER (ORDER BY gsc.po_datetime DESC) AS row_num, gsc.po_id,gsc.po_datetime,gsc.po_content, CASE WHEN gsc.po_point > 0 THEN gsc.po_point ELSE 0 END AS save_point, CASE WHEN gsc.po_point < 0 THEN ABS(gsc.po_point) ELSE 0 END AS use_point, gsc.po_expired,gsc.po_expire_date, CASE WHEN gsc.po_rel_table = '@delivery' THEN SUBSTRING_INDEX(gsc.po_rel_action, ',', 1) ELSE NULL END AS od_id, pph.type,pph.admin_fl FROM g5_point gsc LEFT JOIN pet_point_history pph ON pph.g5_point_id = gsc.po_id WHERE gsc.mb_id = #{mbId}
AND gsc.po_point > 0 AND gsc.po_datetime >= DATE_ADD(NOW(), INTERVAL -3 MONTH)
AND DATE_FORMAT(gsc.po_expire_date, '%Y-%m') = DATE_FORMAT(NOW(), '%Y-%m') AND gsc.po_expired = 0
AND DATE_FORMAT(gsc.po_datetime, '%Y-%m') BETWEEN #{startDate} AND #{endDate}
LIMIT #{pageNo}, #{pageSize}

SELECT IFNULL(mb_point, 0) AS mb_point
   FROM g5_member
   WHERE mb_id = #{mbId}
   AND (mb_leave_date IS NULL OR mb_leave_date = '');

mapper.update:
UPDATE g5_shop_coupon_zone
    SET cz_download = cz_download + 1
WHERE cz_id = #{czId}

mapper.select:
SELECT SQL_CALC_FOUND_ROWS ROW_NUMBER() OVER (ORDER BY gsc.ct_select_time DESC) AS row_num, gsc.it_id, CASE WHEN gsc.io_id != '' THEN GROUP_CONCAT(gsc.ct_option, ' ', (CONCAT(gsc.ct_qty, '개'))) ELSE gsc.ct_option END AS ct_option, gsc.od_id, gsc.mb_id, gsc.it_name, gsc.ct_qty, gsc.io_id, gsc.pet_id, gsc.pet_history_id, gsc.urine_check_history_id, CASE WHEN gsi.it_2 IS NOT NULL AND gsi.it_2 != '' THEN FLOOR((gsi.it_price * ((gsi.it_2) / 100) / 10 ) * 10) ELSE 0 END AS po_point, STR_TO_DATE(SUBSTRING_INDEX(SUBSTRING_INDEX(gsc.ct_history, '|', -2), '|', 1), '%Y-%m-%d') AS ct_history, 15 - DATEDIFF(CURDATE(), STR_TO_DATE(SUBSTRING_INDEX(SUBSTRING_INDEX(gsc.ct_history, '|', -2), '|', 1), '%Y-%m-%d %H:%i:%s')) AS days_left, gsi.it_img1, CASE WHEN ( SELECT COUNT(*) FROM g5_shop_item_use WHERE it_id = gsc.it_id AND od_id = gsc.od_id AND del_fl = 0 ) > 0 THEN 1 ELSE 0 END AS review_fl FROM g5_shop_order gso INNER JOIN g5_shop_cart gsc ON gso.od_id = gsc.od_id INNER JOIN g5_shop_item gsi ON gsi.it_id = gsc.it_id WHERE ( SELECT COUNT(*) FROM g5_shop_item_use WHERE it_id = gsc.it_id AND od_id = gsc.od_id ) = 0 AND gso.od_completion_date >= DATE_SUB(CURDATE(), INTERVAL 15 DAY) AND gsc.ct_status = '완료' AND gsc.mb_id = #{mbId}
AND gsc.it_name = #{searchKeyword}
GROUP BY od_id, it_id LIMIT #{pageNo}, #{pageSize}

