mapper.select:
SELECT vml.level, IFNULL(pmlr.level_type_nm, 'Lv.0') AS level_type_nm, vml.level_nm, vml.total_score AS total_score FROM v_member_level vml LEFT JOIN pet_member_level_role pmlr ON vml.level = pmlr.level AND vml.del_fl = pmlr.del_fl WHERE vml.del_fl = 0
AND vml.mb_id = #{mbId}
ORDER BY vml.total_score DESC;
